import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"思古","description":"","frontmatter":{"title":"思古","date":"2026-11-24T00:00:00.000Z","seq":55,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"愍命","link":"/blogs/楚辞/愍命.html"},"next":{"text":"九叹·远游","link":"/blogs/楚辞/九叹·远游.html"}},"headers":[],"relativePath":"blogs/楚辞/思古.md","filePath":"blogs/楚辞/思古.md"}'),o={name:"blogs/楚辞/思古.md"};function l(n,a,c,m,r,z){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="思古" tabindex="-1">思古 <a class="header-anchor" href="#思古" aria-label="Permalink to &quot;思古&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">冥冥深林兮，树木郁郁。</p><p class="poem-stanza">山参差以崭岩兮，阜杳杳以蔽日。</p><p class="poem-stanza">悲余心之悁悁兮，目眇眇而遗泣。</p><p class="poem-stanza">风骚屑以摇木兮，云吸吸以湫戾。</p><p class="poem-stanza">悲余生之无欢兮，愁倥傯于山陆。</p><p class="poem-stanza">旦徘徊于长阪兮，夕彷徨而独宿。</p><p class="poem-stanza">发披披以鬤鬤兮，躬劬劳而瘏悴。</p><p class="poem-stanza">魂俇俇而南行兮，泣霑襟而濡袂。</p><p class="poem-stanza">心婵媛而无告兮，口噤闭而不言。</p><p class="poem-stanza">违郢都之旧闾兮，回湘、沅而远迁。</p><p class="poem-stanza">念余邦之横陷兮，宗鬼神之无次。</p><p class="poem-stanza">闵先嗣之中绝兮，心惶惑而自悲。</p><p class="poem-stanza">聊浮游于山陿兮，步周流于江畔。</p><p class="poem-stanza">临深水而长啸兮，且倘佯而氾观。</p><p class="poem-stanza">兴离骚之微文兮，冀灵修之壹悟。</p><p class="poem-stanza">还余车于南郢兮，复往轨于初古。</p><p class="poem-stanza">道修远其难迁兮，伤余心之不能已。</p><p class="poem-stanza">背三五之典刑兮，绝洪范之辟纪。</p><p class="poem-stanza">播规矩以背度兮，错权衡而任意。</p><p class="poem-stanza">操绳墨而放弃兮，倾容幸而侍侧。</p><p class="poem-stanza">甘棠枯于丰草兮，藜棘树于中庭。</p><p class="poem-stanza">西施斥于北宫兮，仳倠倚于弥楹。</p><p class="poem-stanza">乌获戚而骖乘兮，燕公操于马圉。</p><p class="poem-stanza">蒯聩登于清府兮，咎繇弃而在野。</p><p class="poem-stanza">盖见兹以永叹兮，欲登阶而狐疑。</p><p class="poem-stanza">乘白水而高骛兮，因徙弛而长词。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">倘佯垆阪沼水深兮，容与汉渚涕淫淫兮，锺牙已死谁为声兮？</p><p class="poem-stanza">纤阿不御焉舒情兮，曾哀悽欷心离离兮，还顾高丘泣如洒兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
